import { Box, Button, Container, Stack, Typography } from "@mui/material";
import masterData from "../../data/masterData.json";
import { ArrowForwardIcon, getIcon } from "../../utils/iconMap";
import { scrollToTop as lenisScrollToTop } from "../LenisSmoothScroll";

interface FooterCtaSectionProps {
  onTalkToExpert?: () => void;
}

export default function FooterCtaSection({ onTalkToExpert }: FooterCtaSectionProps) {
  const { footerCta } = masterData;
  const waveBg = (footerCta as { waveBg?: string }).waveBg || "";

  const handleTalkToExpert = () => {
    if (onTalkToExpert) {
      onTalkToExpert();
      return;
    }
    lenisScrollToTop(false);
  };

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        bgcolor: "#0056D2",
        backgroundImage: waveBg
          ? `linear-gradient(90deg, #003E99 0%, rgba(0,86,210,0.92) 45%, rgba(0,86,210,0.75) 100%), url(${waveBg})`
          : "linear-gradient(100deg, #002B6B 0%, #0056D2 55%, #1A6FE8 100%)",
        backgroundSize: "cover",
        backgroundPosition: "center right",
        py: { xs: 4.5, md: 5 },
      }}
    >
      <Container maxWidth="lg" sx={{ position: "relative", zIndex: 1 }}>
        <Stack
          direction={{ xs: "column", md: "row" }}
          spacing={{ xs: 3, md: 4 }}
          alignItems={{ xs: "flex-start", md: "center" }}
        >
          {/* Left surgery image — visible like design */}
          <Box
            component="img"
            src={footerCta.image}
            alt="Surgeons"
            sx={{
              display: { xs: "none", md: "block" },
              width: 220,
              height: 150,
              objectFit: "cover",
              borderRadius: 2,
              flexShrink: 0,
              boxShadow: "0 8px 24px rgba(0,0,0,0.2)",
            }}
          />

          <Box sx={{ flex: 1 }}>
            <Typography
              sx={{
                color: "#fff",
                fontWeight: 800,
                fontSize: { xs: "1.2rem", md: "1.55rem", lg: "1.7rem" },
                letterSpacing: "0.02em",
                lineHeight: 1.25,
                mb: 0.5,
              }}
            >
              {footerCta.headline}
            </Typography>
            <Typography sx={{ color: "rgba(255,255,255,0.92)", fontSize: { xs: 14.5, md: 16.5 } }}>
              {footerCta.subheadline}
            </Typography>
          </Box>

          <Button
            variant="contained"
            endIcon={<ArrowForwardIcon />}
            onClick={handleTalkToExpert}
            sx={{
              bgcolor: "#fff",
              color: "#0056D2",
              px: 3.25,
              py: 1.35,
              borderRadius: "999px",
              fontWeight: 700,
              fontSize: 14.5,
              "&:hover": { bgcolor: "#F0F6FF" },
              whiteSpace: "nowrap",
              flexShrink: 0,
              alignSelf: { xs: "stretch", sm: "auto" },
            }}
          >
            {footerCta.buttonLabel}
          </Button>
        </Stack>

        <Stack
          direction="row"
          spacing={{ xs: 2.5, md: 4.5 }}
          flexWrap="wrap"
          useFlexGap
          sx={{
            mt: 3.5,
            pt: 2.5,
            borderTop: "1px solid rgba(255,255,255,0.2)",
            justifyContent: { xs: "flex-start", md: "flex-end" },
          }}
        >
          {footerCta.trustPoints.map((point) => {
            const Icon = getIcon(point.icon);
            return (
              <Stack key={point.id} direction="row" spacing={1} alignItems="center">
                <Icon sx={{ color: "#fff", fontSize: 20 }} />
                <Typography sx={{ color: "#fff", fontSize: 12.5, fontWeight: 500 }}>
                  {point.label}
                </Typography>
              </Stack>
            );
          })}
        </Stack>
      </Container>
    </Box>
  );
}
